var builder = DistributedApplication.CreateBuilder(args);

// ---------------------------------------------------------------------------
// Infrastructure (Docker containers). Data volumes keep the data between runs.
// Passwords are generated by Aspire and stored in the AppHost user-secrets.
// ---------------------------------------------------------------------------

// Mongo: listening_events, user catalogs, generated_cities, upload/import tasks, Last.fm accounts, sessions, users
var mongo = builder.AddMongoDB("mongo")
    .WithDataVolume()
    .WithLifetime(ContainerLifetime.Persistent)
    .WithMongoExpress();
var cityfyDb = mongo.AddDatabase("cityfy");

// PostgreSQL: MusicBrainz genres/artists (in production: the shared server of the cluster, data/postgres)
var postgres = builder.AddPostgres("postgres")
    .WithImageTag("17-alpine")
    .WithDataVolume("cityfy-postgres-data")
    .WithLifetime(ContainerLifetime.Persistent);
var musicBrainzDb = postgres.AddDatabase("musicbrainz");

// RabbitMQ: event bus of the pipeline (see ServiceDefault/Contracts/PipelineMessages.cs)
var broker = builder.AddRabbitMQ("broker")
    .WithDataVolume()
    .WithLifetime(ContainerLifetime.Persistent)
    .WithManagementPlugin();

// Secrets: set once in the AppHost user-secrets or when the dashboard asks for them.
// Last.fm application (https://www.last.fm/api/account/create): "Parameters:lastfm-api-key" and
// "Parameters:lastfm-shared-secret"
var lastFmApiKey = builder.AddParameter("lastfm-api-key", secret: true);
var lastFmSharedSecret = builder.AddParameter("lastfm-shared-secret", secret: true);

// ---------------------------------------------------------------------------
// Services
// ---------------------------------------------------------------------------

var retrieveDumpSpotify = builder.AddProject<Projects.CityFy_Retrieve_Dump_Spotify>("RetrieveDumpSpotify")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(broker)
    .WaitFor(broker);

// Last.fm: history import and polling of the linked accounts ('lastfm_accounts', 'lastfm_import_tasks')
var retrieveLastFm = builder.AddProject<Projects.CityFy_Retrieve_LastFm>("RetrieveLastFm")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(broker)
    .WaitFor(broker)
    .WithEnvironment("LastFm__ApiKey", lastFmApiKey)
    .WithEnvironment("LastFm__SharedSecret", lastFmSharedSecret);

var retrieveMusicBrainz = builder.AddProject<Projects.CityFy_Retrieve_MusicBrainz>("RetrieveMusicBrainz")
    .WithHttpHealthCheck("/health")
    .WithReference(musicBrainzDb)
    .WaitFor(musicBrainzDb)
    .WithReference(broker)   // publishes CatalogUpdated after an import
    .WaitFor(broker);

// Catalog calls the MusicBrainz read API (artist resolve, genre graph) via service discovery
var catalog = builder.AddProject<Projects.CityFy_Catalog>("Catalog")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(retrieveMusicBrainz)
    .WaitFor(retrieveMusicBrainz)
    .WithReference(broker)
    .WaitFor(broker);

// CityGenerator: generated cities of the users; asks Catalog for the city data, owns 'generated_cities'
var cityGenerator = builder.AddProject<Projects.CityFy_CityGenerator>("CityGenerator")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(catalog)
    .WaitFor(catalog)
    .WithReference(broker)
    .WaitFor(broker);

// Orchestrator: ListeningImported -> (debounce) -> RefreshCatalogRequested -> UserCatalogUpdated/CatalogRefreshFailed
var orchestrator = builder.AddProject<Projects.CityFy_Orchestrator>("Orchestrator")
    .WithHttpHealthCheck("/health")
    .WithReference(cityfyDb)
    .WaitFor(cityfyDb)
    .WithReference(broker)
    .WaitFor(broker);

// Public API: the only service meant to be reachable from browsers (session, /api/v1).
// Last.fm redirects to its /api/v1/auth/lastfm/callback (LastFm:CallbackUrl of RetrieveLastFm).
var api = builder.AddProject<Projects.CityFy_Api>("Api")
    .WithHttpHealthCheck("/health")
    .WithReference(catalog).WaitFor(catalog)
    .WithReference(cityGenerator).WaitFor(cityGenerator)
    .WithReference(orchestrator).WaitFor(orchestrator)
    .WithReference(retrieveDumpSpotify).WaitFor(retrieveDumpSpotify)
    .WithReference(retrieveLastFm).WaitFor(retrieveLastFm)
    // Anonymous sessions ('anonymous_sessions') and the admin database browser
    .WithReference(cityfyDb).WaitFor(cityfyDb)
    // Live events: consumes NowPlayingChanged, publishes UserActive
    .WithReference(broker).WaitFor(broker)
    // Admin panel: MusicBrainz import, read-only database browser, links to the log tools
    .WithReference(retrieveMusicBrainz)
    .WithReference(musicBrainzDb)
    .WithEnvironment("Admin__RabbitMqManagementUrl", broker.GetEndpoint("management"))
    .WithEnvironment("Admin__DashboardUrl", builder.Configuration["ASPNETCORE_URLS"]?.Split(';')[0] ?? "");

// Frontend (Angular, cityfy-web): ng serve on http://127.0.0.1:4200 with a proxy /api -> Api.
// Browser, Last.fm callback and session cookie all live on this single origin.
var web = builder.AddJavaScriptApp("Web", "../../cityfy-web", "start")
    .WithHttpEndpoint(port: 4200, isProxied: false)
    .WithExternalHttpEndpoints()
    .WithReference(api)
    .WaitFor(api);

// ---------------------------------------------------------------------------
// Optional public tunnel (ngrok): set "Ngrok:Url" (e.g. https://<name>.ngrok-free.dev) to enable.
// The tunnel targets the FRONTEND (not the Api): the public origin then serves both the app and
// /api through the dev-server proxy, so the session cookie stays on one origin.
// Uses the local ngrok CLI and its own authtoken (ngrok config add-authtoken ...).
// Set <Ngrok:Url>/api/v1/auth/lastfm/callback as the callback of the Last.fm application.
// ---------------------------------------------------------------------------
var publicUrl = builder.Configuration["Ngrok:Url"]?.TrimEnd('/');
if (!string.IsNullOrWhiteSpace(publicUrl))
{
    builder.AddExecutable("Ngrok", "ngrok", "../../cityfy-web",
            "http", $"--url={publicUrl}", "--log=stdout", "--log-format=logfmt", "http://127.0.0.1:4200")
        .WaitFor(web);

    // Login and redirects must use the public origin when the app is opened through the tunnel
    retrieveLastFm.WithEnvironment("LastFm__CallbackUrl", $"{publicUrl}/api/v1/auth/lastfm/callback");
    api.WithEnvironment("Frontend__BaseUrl", publicUrl);
}

builder.Build().Run();
